import json
from pathlib import Path
from .repository_text import write_english_report


def generate(output='docs/industrial-cases.md'):
    lines=['# Real-World Enterprise Demand Cases','',
        'These are system run examples, not a human relevance evaluation. Recommendations and missing items are generated by the model. Candidates may have only adjacent capabilities; this does not establish that they meet the enterprise technical requirements.','']
    for p in sorted(Path('artifacts/demand-cases').glob('*.json')):
        r=json.loads(p.read_text()); q=r['query']
        lines.extend([f"## {q['title']}",'',f"Demand source: {q['source']}",f"Details: {q.get('url','')}",'',f"Run status: {r['status']}; total time {r['seconds']:.2f} seconds.",''])
        for method,result in r['baselines'].items():
            lines.append(f"- {method}: "+', '.join(x['name'] or x['id'] for x in result))
        for x in r.get('agent',{}).get('results',[]):
            lines.extend(['',f"### {x['expert']['name']}",'',x['reason'],'',
                'Requirements not supported by evidence: '+'; '.join(x['missing']) if x['missing'] else 'The model did not list missing items; manual verification is still required.',''])
            for e in x['evidence']:
                lines.append(f"- `{e['id']}`, source `{e['source']}`: {e['text'][:350].replace(chr(10),' ')}")
        lines.extend(['',f'Full results and model trace: `{p}`.',''])
    write_english_report(output,'\n'.join(lines)+'\n')
    return output
